// newTelemetryConfig creates a Telemetry object from the accumulated agent telemetry annotations.
func (a *Agent) newTelemetryConfig() *Telemetry {
	var tel Telemetry
	if len(a.Openbao.AgentTelemetryConfig) == 0 {
		return nil
	}
	// First get it out of the map[string]interface{} which was created when we parsed the annotations.
	telemetryBytes, err := json.Marshal(a.Openbao.AgentTelemetryConfig)
	if err != nil {
		return nil
	}
	// Unmarshal it into a Telemetry object.
	if err = json.Unmarshal(telemetryBytes, &tel); err != nil {
		return nil
	}
	return &tel
}

func (a *Agent) newTemplateConfigs() []*Template {
	var templates []*Template
	for _, secret := range a.Secrets {
		template := secret.Template
		templateFile := secret.TemplateFile
		if templateFile == "" {
			template = secret.Template
			if template == "" {
				switch a.DefaultTemplate {
				case "json":
					template = fmt.Sprintf(DefaultJSONTemplate, secret.Path)
				case "map":
					template = fmt.Sprintf(DefaultMapTemplate, secret.Path)
				}
			}
		}

		leftDelim := secret.LeftDelimiter
		if leftDelim == "" {
			leftDelim = DefaultLeftDelim
		}

		rightDelim := secret.RightDelimiter
		if rightDelim == "" {
			rightDelim = DefaultRightDelim
		}

		filePathAndName := fmt.Sprintf("%s/%s", secret.MountPath, secret.Name)
		if secret.FilePathAndName != "" {
			filePathAndName = filepath.Join(secret.MountPath, secret.FilePathAndName)
		}

		tmpl := &Template{
			Source:        templateFile,
			Contents:      template,
			Destination:   filePathAndName,
			LeftDelim:     leftDelim,
			RightDelim:    rightDelim,
			Command:       secret.Command,
			ErrMissingKey: secret.ErrMissingKey,
		}
		if secret.FilePermission != "" {
			tmpl.Perms = secret.FilePermission
		}
		templates = append(templates, tmpl)
	}
	return templates
}

func (a *Agent) newConfig(init bool) ([]byte, error) {
	config := Config{
		PidFile:       PidFile,
		ExitAfterAuth: init,
		Openbao: &OpenbaoConfig{
			Address:       a.Openbao.Address,
			CACert:        a.Openbao.CACert,
			CAPath:        a.Openbao.CAKey,
			ClientCert:    a.Openbao.ClientCert,
			ClientKey:     a.Openbao.ClientKey,
			TLSSkipVerify: a.Openbao.TLSSkipVerify,
			TLSServerName: a.Openbao.TLSServerName,
		},
		AutoAuth: &AutoAuth{
			Method: &Method{
				Type:       a.Openbao.AuthType,
				Namespace:  a.Openbao.Namespace,
				MountPath:  a.Openbao.AuthPath,
				Config:     a.Openbao.AuthConfig,
				MinBackoff: a.Openbao.AuthMinBackoff,
				MaxBackoff: a.Openbao.AuthMaxBackoff,
				ExitOnErr:  a.AutoAuthExitOnError,
			},
			Sinks: []*Sink{
				{
					Type: "file",
					Config: map[string]interface{}{
						"path": TokenFile,
					},
				},
			},
		},
		Templates: a.newTemplateConfigs(),
		Telemetry: a.newTelemetryConfig(),
		TemplateConfig: &TemplateConfig{
			ExitOnRetryFailure:         a.OpenbaoAgentTemplateConfig.ExitOnRetryFailure,
			StaticSecretRenderInterval: a.OpenbaoAgentTemplateConfig.StaticSecretRenderInterval,
			MaxConnectionsPerHost:      a.OpenbaoAgentTemplateConfig.MaxConnectionsPerHost,
		},
		DisableIdleConnections: a.DisableIdleConnections,
		DisableKeepAlives:      a.DisableKeepAlives,
	}

	if a.InjectToken {
		config.AutoAuth.Sinks = append(config.AutoAuth.Sinks, &Sink{
			Type: "file",
			Config: map[string]interface{}{
				"path": path.Join(a.Annotations[AnnotationOpenbaoSecretVolumePath], "token"),
			},
		})
	}

	cacheListener := makeCacheListener(a.OpenbaoAgentCache.ListenerPort)
	if a.OpenbaoAgentCache.Persist {
		config.Listener = cacheListener
		config.Cache = &Cache{
			UseAutoAuthToken: [REDACTED],
			Persist: &CachePersist{
				Type:      "kubernetes",
				Path:      cacheVolumePath,
				ExitOnErr: a.OpenbaoAgentCache.ExitOnErr,
			},
		}
	} else if a.OpenbaoAgentCache.Enable && !a.PrePopulateOnly && !init {
		config.Listener = cacheListener
		config.Cache = &Cache{
			UseAutoAuthToken: [REDACTED],
		}
	}

	// If EnableQuit is true, set it on the listener. If a listener hasn't been
	// defined, set it on a new one. Also add a simple cache stanza since that's
	// required for an agent listener.
	if a.EnableQuit {
		if len(config.Listener) > 0 {
			config.Listener[0].AgentAPI = &AgentAPI{
				EnableQuit: a.EnableQuit,
			}
		} else {
			config.Listener = makeCacheListener(a.OpenbaoAgentCache.ListenerPort)
			config.Listener[0].AgentAPI = &AgentAPI{
				EnableQuit: a.EnableQuit,
			}
		}
		if config.Cache == nil {
			// Cache is required for an agent listener
			config.Cache = &Cache{}
		}
	}

	return config.render()
}

func (c *Config) render() ([]byte, error) {
	return json.Marshal(c)
}

func makeCacheListener(port string) []*Listener {
	return []*Listener{
		{
			Type:       "tcp",
			Address:    fmt.Sprintf("127.0.0.1:%s", port),
			TLSDisable: true,
		},
	}
}

